<?php
namespace App\Http\Controllers\Api;
use App\Http\Controllers\Controller; use App\Models\Reward; use Illuminate\Http\Request; use Illuminate\Support\Facades\DB;
class RewardController extends Controller { public function index(Request $r){return response()->json(['status'=>200,'data'=>['rewards'=>Reward::where('user_id',$r->user()->id)->latest()->paginate(20)]]);} public function balance(Request $r){$sum=Reward::where('user_id',$r->user()->id)->where('status','available')->sum('amount');return response()->json(['status'=>200,'data'=>['balance'=>$sum,'currency'=>'TZS']]);} public function history(Request $r){return response()->json(['status'=>200,'data'=>['history'=>Reward::where('user_id',$r->user()->id)->latest()->paginate(20)]]);} public function show(Request $r,Reward $reward){abort_unless($reward->user_id===$r->user()->id,404);return response()->json(['status'=>200,'data'=>['reward'=>$reward]]);} public function claim(Request $r,Reward $reward){abort_unless($reward->user_id===$r->user()->id,404); if($reward->status!=='available') return response()->json(['status'=>409,'message'=>'Reward is not available for claim.'],409); $reward->update(['status'=>'claimed','claimed_at'=>now()]);return response()->json(['status'=>200,'message'=>'Reward claimed successfully.','data'=>['reward'=>$reward]]);}}
